"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[9350],{13813:e=>{e.exports=JSON.parse('{"functions":[{"name":"show","desc":"Parents in as many pending placements as the frame has left. Runs in\\n`Phases.Update`, alongside `build`, acting on the intent `detail` set last\\nframe.\\n\\nDraining runs before enqueueing: hierarchies already part-way into the world\\nshould finish before more are started, or everything sits half-assembled at\\nonce.\\n\\nAlways reveals at least one placement per pass, even over budget, so a tight\\nbudget slows the reveal instead of stalling it forever.","params":[{"name":"world","desc":"","lua_type":"jecs.World"}],"returns":[{"desc":"Update function.","lua_type":"() -> ()"},{"desc":"Cleanup function; drops any half-streamed hierarchies.","lua_type":"() -> ()"}],"function_type":"static","source":{"line":42,"path":"src/main/server/systems/maze/show.luau"}}],"properties":[],"types":[],"name":"show","desc":"Reveals placements gradually. Any placement whose entity has `Render` but not\\n`Rendered` is streamed back into its detail block through [slowParent].\\n\\n`Render` is intent, `Rendered` is reality. Reconciling one to the other is\\ngradual twice over: only so many placements are admitted per frame, and each\\nplacement\'s own hierarchy is admitted node by node, so even a single large\\nroom never lands in one parent write.\\n\\nEntities tagged `Processing` are skipped \u2014 their model is mid-stream and must\\nnot be touched.","tags":["server-system"],"realm":["Server"],"source":{"line":17,"path":"src/main/server/systems/maze/show.luau"}}')}}]);